(function(){const G = window.__game, A = G.Air.s, K = G.Keys, TH = G.THREE_, id = 'vixen';
G.save.set.dev = true; G.save.set.cycle = 0; G.Dev.god = true; G.save.air.own[id] = true; G.Fly.tags();
G.UI.devAct('tpair'); for (let i = 0; i < 40; i++) G.Chunks.update(A.cx - 150, A.cz + 60, 3);
G.Foot.exit();
const P = G.Fly.planes.find(p => p.id === id);
G.Foot.x = P.x + 3.0; G.Foot.z = P.z; G.Foot.y = P.y - P.spec.cgY; G.Fly.scan();
if (!G.Fly.near) return 'no near: ' + G.Foot.on;
G.Fly.useNear();
const rw = G.AIR.RW; P.x = A.cx + rw.u0 + 30; P.z = A.cz; P.y = G.Air.groundY(P.x, P.z) + P.spec.cgY; P.home.x = P.x; P.q.setFromAxisAngle(new TH.Vector3(0, 1, 0), Math.PI / 2);
for (let i = 0; i < 30; i++) G.Chunks.update(P.x, P.z, 3);
const S = P.spec, dt = 1 / 60, rows = [], dg = (r) => (r / Math.PI * 180).toFixed(1);
let t = 0, phase = 'roll', tAir = 0, tRel = 0, tRoll = 0, tEnd = 0;
const sample = () => rows.push([t.toFixed(0), phase, (P.speed * 3.6).toFixed(0), (P.agl || 0).toFixed(0), P.vy.toFixed(1), dg(P.pitch), dg(P.bank), dg(P.alpha || 0), P.thr.toFixed(2), P.gnd ? 'G' : 'A', P.st, (P.hdg || 0).toFixed(0)].join(' '));
for (let i = 0; i < 60 * 70; i++) {
  K.ShiftLeft = P.thr < 1; K.KeyS = false; K.KeyD = false; K.KeyZ = false; K.KeyW = false;
  if (phase === 'roll' && P.speed > S.Vr * 1.04) phase = 'climb';
  if (phase === 'climb') { K.KeyS = P.agl < 10 ? P.pitch < 0.17 : P.pitch < 0.13; K.KeyW = P.agl >= 10 && P.pitch > 0.19; if (P.agl > 80) { phase = 'cruise'; tRel = t; } }
  if (phase === 'cruise' && t - tRel > 9) { phase = 'bank'; tRoll = t; }
  if (phase === 'bank') { K.KeyD = true; if (t - tRoll > 4) { phase = 'level'; tRoll = t; } }
  if (phase === 'level' && t - tRoll > 8) { phase = 'slow'; tEnd = t; }
  if (phase === 'slow') { K.ShiftLeft = false; K.KeyZ = true; }
  G.stepSim(dt); t += dt; if (i % 60 === 0) sample(); if (P.st === 'wreck') { sample(); break; }
}
K.ShiftLeft = K.KeyS = K.KeyD = K.KeyZ = false;
return rows.join('\n');})()
